//! Primary keys: UUID v7, generated by the application (specification §18).
//!
//! UUID v7 starts with a millisecond timestamp, so keys sort by creation time,
//! which keeps B-tree indexes compact and suits future partitioning and imports.

use uuid::Uuid;

/// A new UUID v7. Successive calls in one process are strictly increasing.
pub fn new_id() -> Uuid {
    Uuid::now_v7()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_version_7() {
        assert_eq!(new_id().get_version_num(), 7);
    }

    #[test]
    fn successive_ids_are_strictly_increasing() {
        let ids: Vec<Uuid> = (0..10_000).map(|_| new_id()).collect();
        assert!(
            ids.windows(2).all(|w| w[0] < w[1]),
            "ids must sort in creation order"
        );
    }

    #[test]
    fn ids_generated_across_threads_are_unique() {
        let handles: Vec<_> = (0..4)
            .map(|_| std::thread::spawn(|| (0..2_500).map(|_| new_id()).collect::<Vec<_>>()))
            .collect();
        let mut all: Vec<Uuid> = handles.into_iter().flat_map(|h| h.join().unwrap()).collect();
        let count = all.len();
        all.sort();
        all.dedup();
        assert_eq!(all.len(), count);
    }
}
